function speakable(md) {
  return md.replace(/```[\s\S]*?```/g, "").replace(/^\s*\|.*\|\s*$/gm, "").replace(/[*_`#>]/g, "").replace(/^\s*[-•]\s+(.*?)\s*$/gm, (_, item) => /[.!?:;]$/.test(item) ? item : `${item}.`).replace(/\[([^\]]+)\]\([^)]+\)/g, "$1").replace(/€\s?HT\b/g, "euros hors taxes").replace(/€\s?TTC\b/g, "euros TTC").replace(/€/g, "euros").replace(/\bHT\b/g, "hors taxes").replace(/(\d)\s?%/g, "$1 pour cent").replace(/\s+→\s+/g, ", ").replace(/\n{2,}/g, "\n").trim();
}
function voiceDecision(t) {
  const s2 = t.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-z' ]/g, " ").replace(/\s+/g, " ").trim();
  if (/^(je valide|valider|valide|oui je valide|c'est valide|je confirme|confirmer)( le devis| la creation)?( merci)?$/.test(s2)) return "valider";
  if (/^(non|refuser|je refuse|refuse|annuler|annule|stop|ne fais rien)( merci)?$/.test(s2)) return "refuser";
  return null;
}
function matchOption(t, options) {
  const norm = (x) => x.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, " ").trim();
  const s2 = norm(t);
  const exact = options.filter((o) => norm(o) === s2);
  if (exact.length === 1) return exact[0];
  const inside = options.filter((o) => norm(o).length >= 2 && ` ${s2} `.includes(` ${norm(o)} `));
  return inside.length === 1 ? inside[0] : null;
}

