  const VOICE_IDLE_MS = 30 * 6e4;
  const VOICE_MAX_CHARS = 1500;
  const voiceReply = (items, from) => {
    const parts2 = [];
    let waiting = false;
    for (const it of items.slice(from)) {
      if (it.type === "assistant") parts2.push(it.text);
      else if (it.type === "draft") {
        const ht = it.lignes.reduce((a, l) => a + Number(l.quantite) * Number(l.prix_unitaire_ht), 0);
        if (Number.isFinite(ht)) parts2.push(`Brouillon pr\xEAt : ${it.titre}, ${Math.round(ht).toLocaleString("fr-FR")} \u20AC HT.`);
      } else if (it.type === "choice" && it.open) {
        waiting = true;
        parts2.push(`${it.question} ${it.options.length ? `Vous pouvez r\xE9pondre : ${it.options.slice(0, -1).join(", ")}${it.options.length > 1 ? " ou " : ""}${it.options.at(-1)}.` : ""}`);
      } else if (it.type === "confirm" && it.state === "attente") {
        waiting = true;
        parts2.push(`Je dois \xAB ${toolLabel(it.tool)} \xBB dans Interfast. Pour confirmer, dites : je valide. Sinon, dites : non.`);
      }
    }
    let text3 = speakable(parts2.join("\n")).replace(/\n+/g, " ").trim();
    if (text3.length > VOICE_MAX_CHARS) text3 = `${text3.slice(0, VOICE_MAX_CHARS).replace(/\s+\S*$/, "")}\u2026 La suite est dans l\u2019appli Envo.`;
    return { text: text3 || "C\u2019est not\xE9.", waiting };
  };
  app2.post("/api/voix", async (c2) => {
    const auth = c2.req.header("authorization") ?? "";
    const b = await readJson(c2);
    const token = (/^Bearer\s+(.+)$/i.exec(auth)?.[1] ?? String(b.cle ?? "")).trim();
    if (overRate(`voix-ip:${clientIp(c2)}`, 120, 36e5)) return c2.json({ reponse: "Trop de demandes, r\xE9essayez plus tard.", erreur: "debit" }, 429);
    const row = token.length >= 20 ? (await db2.query("SELECT id, user_id FROM voice_tokens WHERE token_hash = $1", [sha2562(token)]))[0] : void 0;
    if (!row) return c2.json({ reponse: "Cl\xE9 vocale inconnue. Cr\xE9ez-en une dans Envo, Param\xE8tres, Siri.", erreur: "cle" }, 401);
    const u = (await db2.query("SELECT id, email, name FROM users WHERE id = $1", [row.user_id]))[0];
    if (!u) return c2.json({ reponse: "Compte introuvable.", erreur: "cle" }, 401);
    await db2.query("UPDATE voice_tokens SET last_used_at = $2 WHERE id = $1", [row.id, now2()]);
    if (!llm || !cfg2.anthropic) return c2.json({ reponse: "L\u2019assistante n\u2019est pas activ\xE9e sur le serveur.", erreur: "assistante" }, 503);
    if (overRate(`turn:${u.id}`, 120, 36e5)) return c2.json({ reponse: "Trop de messages en une heure. Patientez un peu.", erreur: "debit" }, 429);
    const said = str(b.texte ?? b.text, 4e3);
    if (!said) return c2.json({ reponse: "Je n\u2019ai rien entendu. Redites-moi.", attente: true }, 400);
    const fresh = b.nouvelle === true || /^(nouvelle (conversation|séance|seance)|recommence|on recommence)\b/i.test(said);
    let conv = fresh ? null : (await db2.query(`SELECT * FROM conversations WHERE user_id = $1 AND kind = 'voix' AND status <> 'termine' AND updated_at > $2 ORDER BY updated_at DESC LIMIT 1`, [u.id, new Date(now2().getTime() - VOICE_IDLE_MS)]))[0] ?? null;
    if (fresh && /^(nouvelle (conversation|séance|seance)|recommence|on recommence)\W*$/i.test(said)) {
      await createConversation(u, "voix");
      return c2.json({ reponse: "D\u2019accord, on repart de z\xE9ro. Je vous \xE9coute.", attente: true });
    }
    conv ??= await ownConv(u.id, await createConversation(u, "voix"));
    if (!conv) return c2.json({ reponse: "Impossible d\u2019ouvrir une s\xE9ance.", erreur: "interne" }, 500);
    if (busy.has(conv.id)) return c2.json({ reponse: "Je r\xE9ponds d\xE9j\xE0 \xE0 votre demande pr\xE9c\xE9dente. Un instant.", attente: true }, 409);
    const answers = [];
    let text3 = said;
    for (const w of conv.pending?.waiting ?? []) {
      if (w.kind === "confirm") {
        const d2 = voiceDecision(said);
        if (d2) {
          answers.push({ toolUseId: w.toolUseId, approved: d2 === "valider" });
          text3 = "";
        }
      } else {
        answers.push({ toolUseId: w.toolUseId, choice: matchOption(said, w.options) ?? said });
        text3 = "";
      }
    }
    const before = toView(await history(conv.id), conv.pending, await actionStates(conv.id)).length;
    busy.add(conv.id);
    const cv = conv;
    c2.header("Content-Type", "application/json; charset=utf-8");
    c2.header("X-Accel-Buffering", "no");
    c2.header("Cache-Control", "no-store");
    return stream(c2, async (st) => {
      const ping = setInterval(() => void st.write(" ").catch(() => {
      }), 15e3);
      let body;
      try {
        const out = await executeTurn(u, cv, text3, answers, () => {
        }, { effort: "low" });
        const r = voiceReply(out.items, before);
        body = { reponse: r.text, attente: r.waiting, conversation: cv.id, lien: `${origin}/#/devis/${cv.id}` };
      } catch (e) {
        console.error("voix :", e.message);
        body = { reponse: "Je n\u2019ai pas pu r\xE9pondre. R\xE9essayez dans un instant.", erreur: "interne", attente: false };
      } finally {
        clearInterval(ping);
        busy.delete(cv.id);
      }
      await st.write(JSON.stringify(body)).catch(() => {
      });
    });
  });
