    const last = (await db2.query("SELECT overview_stats FROM settings WHERE user_id = $1", [u.id]))[0]?.overview_stats ?? null;
    const base = { configured: !!s2.mcp_url, host: host(s2.mcp_url), keyHint: s2.mcp_key_hint, week: { ...stats, top }, lastRead: last };
    const mcp = mcpFor(s2);
